const assert = require('assert');
const fs = require('fs');
const jsdom = require('jsdom');
const Util = require('../../../../report/html/renderer/util.js');
const URL = require('../../../../lib/url-shim.js');
const DOM = require('../../../../report/html/renderer/dom.js');
const DetailsRenderer = require('../../../../report/html/renderer/details-renderer.js');
const CategoryRenderer = require('../../../../report/html/renderer/category-renderer.js');
const sampleResultsOrig = require('../../../results/sample_v2.json');

const TEMPLATE_FILE = fs.readFileSync(__dirname +
    '/../../../../report/html/templates.html', 'utf8');

const {document} = new jsdom.JSDOM(TEMPLATE_FILE).window;
const dom = new DOM(document);
const detailsRenderer = new DetailsRenderer(dom);
const pwaRenderer = new CategoryRenderer(dom, detailsRenderer);

const sampleResults = Util.prepareReportResult(sampleResultsOrig);

// Clone category to allow modifications.
const pwaCategory = sampleResults.categories.pwa;
const category = JSON.parse(JSON.stringify(pwaCategory));

// Set the PWA score to null to simulate the issue
category.score = null;

// Render the PWA category
const categoryElem = pwaRenderer.render(category, sampleResults.categoryGroups);

// Check the PWA gauge
const gaugeElem = categoryElem.querySelector('.lh-gauge--pwa__wrapper');
assert.ok(gaugeElem, 'PWA gauge should be present');

// Check if the gauge is styled correctly
const percentageElem = gaugeElem.querySelector('.lh-gauge__percentage');
assert.strictEqual(percentageElem.textContent, '?', 'PWA gauge should display a question mark for null score');
assert.strictEqual(percentageElem.title, Util.UIStrings.errorLabel, 'PWA gauge should have error label');
